// ---- пункт b: авто-генерация Gemini-ключей из данных сети ----
// Покрывает ВСЕ сочетания версия×семейство×суффикс, чтобы имя вроде "3.5 Flash Lite" /
// "3.1 Pro Extended" маппилось точно, а не падало на дефолт. Только ДОБАВЛЯЕТ отсутствующие
// ключи (проверка ниже) → существующие явные ключи не трогает, риск слома ≈ 0.
// Окно: 1.5 Pro = 2M, остальные = 1M (на цифру не влияет — она от порога 128000).
(function () {
  var V = ['1.5', '2.0', '2.5', '3.1', '3.5', '3.6', '3.7'];
  var F = ['Flash', 'Pro', 'Ultra'];
  var S = ['', ' Lite', ' Расширенная', ' Extended'];
  function win(v, f) { return (v === '1.5' && f === 'Pro') ? 2097152 : 1048576; }
  V.forEach(function (v) {
    F.forEach(function (f) {
      S.forEach(function (s) {
        var key = v + ' ' + f + s;
        if (!ModelConfig.models[key]) {
          ModelConfig.models[key] = {
            name: 'Gemini ' + key,
            provider: 'Google',
            contextLimit: win(v, f),
            description: 'Gemini (имя из данных сети, авто-ключ)'
          };
        }
      });
    });
  });
})();

// v49: переопределение окон под реальную линейку веб-UI (а не линейку 3.7-анонса).
// Авто-генерация выше даёт 1.5 Pro=2M, остальные=1M — но в веб-UI у Pro окно 128K.
// Flash/Flash-Lite оставляем 1M (совпадает с авто). Записи 3.7-family НЕ становятся
// семейными дефолтами (см. familyDefaults выше) и оставлены только для распознавания
// версий, пришедших из сети.
(function () {
  // сверить: Pro-семейство (3.1..3.7) → 128K в веб; Flash/Flash-Lite → 1M (уже так).
  ['3.1 Pro', '3.5 Pro', '3.6 Pro', '3.7 Pro'].forEach(function (k) {
    var r = ModelConfig.models[k];
    if (r) r.contextLimit = 128000;
  });
  // гарантируем, что Flash/Flash-Lite остаются 1M (как авто-генерацией)
  ['3.6 Flash', '3.5 Flash Lite'].forEach(function (k) {
    var r = ModelConfig.models[k];
    if (r && r.contextLimit !== 1048576) r.contextLimit = 1048576;
  });
})();

/* ==== adapters/base-adapter.js ==== */
/**
 * Базовый класс для всех адаптеров сайтов.
 * Определяет общий интерфейс, который должен реализовать каждый адаптер.
 * 
 * Паттерн: Strategy (Стратегия)
 * Каждый адаптер — это стратегия извлечения диалогов из DOM конкретного сайта.
 *
 * Типизация (шаг 4 Фазы 1): формы берутся из types/adapter.d.ts. Литеральный
 * `import type` здесь невозможен — файл грузится как классический скрипт контента
 * (manifest.json) и склеивается исходником в new Function() песочницами тестов,
 * поэтому типы подключаются JSDoc-ссылкой import() (комментарии, рантайм не меняется).
 */

/**
 * Сообщение в форме адаптера — контракт Adapter.extractMessages()
 * (types/adapter.d.ts). НЕ путать с Message из types/message.d.ts: там поле text.
 *
 * Имя с префиксом — НЕ по вкусу, а по необходимости: файлы адаптеров не являются
 * модулями (обычные скрипты, склеиваемые исходником), поэтому при allowJs все
 * typedef-имена попадают в одну общую область и одноимённые дают TS2300. Поэтому
 * каждый адаптер заводит свой алиас на ОДНО и то же имя типа из types/adapter.d.ts.
 * @typedef {import('../types/adapter').ExtractedMessage} BaseExtractedMessage
 */

/**
 * Контракт адаптера, который реализует BaseAdapter (types/adapter.d.ts).
 * @typedef {import('../types/adapter').Adapter} BaseAdapterContract
 */

/**
 * Родитель для поиска: Document (весь документ) либо Element (поддерево).
 * Изначально аннотировали как Element — tsc ругался, что у Document нет
 * attributes/classList/className и ещё 116 свойств (TS2740).
 * @typedef {Document|Element} ParentNode
 */

/** BaseAdapter — реализация контракта BaseAdapterContract (types/adapter.d.ts). */
class BaseAdapter {
  constructor() {
    // Название сайта (будет переопределено в наследниках)
    this.siteName = 'base';
    
    // Селектор контейнера с диалогами (переопределить в наследнике)
    this.dialogContainerSelector = '';
    
    // Селекторы для сообщений пользователя и модели (переопределить)
    this.userMessageSelector = '';
    this.modelMessageSelector = '';
  }

  /**
   * Проверяет, находимся ли мы на странице диалога этого сайта.
   * @returns {boolean}
   */
  isOnDialogPage() {
    throw new Error('Метод isOnDialogPage() должен быть переопределён');
  }

  /**
   * Извлекает все сообщения из диалога.
   * @returns {BaseExtractedMessage[]}
   */
  extractMessages() {
    throw new Error('Метод extractMessages() должен быть переопределён');
  }

  /**
   * Собирает полный текст диалога для оценки токенов.
   * @returns {string}
   */
  getFullDialogText() {
    const messages = this.extractMessages();
    return messages.map(msg => msg.content).join('\n');
  }

  /**
   * Возвращает количество сообщений в диалоге.
   * @returns {number}
   */
  getMessageCount() {
    return this.extractMessages().length;
  }

  /**
   * Определяет модель ИИ по DOM (если возможно).
   * @returns {string|null} - название модели или null
   */
  detectModel() {
    return null; // По умолчанию не умеем определять
  }

  /**
   * Безопасное получение текста из элемента.
   * @param {Element} element
   * @returns {string}
   */
  _getTextContent(element) {
    return element ? element.textContent.trim() : '';
  }

  /**
   * Безопасный querySelector с проверкой.
   * @param {string} selector
   * @param {ParentNode} [parent] - Document по умолчанию
   * @returns {Element|null}
   */
  _safeQuerySelector(selector, parent = document) {
    try {
      return parent.querySelector(selector);
    } catch (e) {
      aiCmDiagWarn('adapter:base:safeQuerySelector', `Ошибка селектора "${selector}":`, e);
      return null;
    }
  }

  /**
   * Безопасный querySelectorAll с проверкой.
   * Ветка ошибки возвращает пустой массив, а не NodeList: у NodeList есть .item(),
   * у массива нет (TS2741). Потребители берут только .length и срез в массив
   * (Array.prototype.slice.call в qwen-adapter.js:143), поэтому обе формы годятся.
   * @param {string} selector
   * @param {ParentNode} [parent] - Document по умолчанию
   * @returns {NodeList|Element[]}
   */
  _safeQuerySelectorAll(selector, parent = document) {
    try {
      return parent.querySelectorAll(selector);
    } catch (e) {
      aiCmDiagWarn('adapter:base:safeQuerySelectorAll', `Ошибка селектора "${selector}":`, e);
      return [];
    }
  }
}

// Экспортируем для использования в других скриптах
if (typeof module !== 'undefined' && module.exports) {
  module.exports = BaseAdapter;
}

/* ==== adapters/chatgpt-adapter.js ==== */
/**
 * Адаптер для ChatGPT (chatgpt.com).
 *
 * Типизация (шаг 4 Фазы 1): формы — из types/adapter.d.ts. Литеральный `import type`
 * невозможен (файл — классический скрипт контента плюс склейка исходника в
 * new Function()/eval песочницами тестов), поэтому типы подключены JSDoc-ссылкой import().
 */

/**
 * Сообщение в форме адаптера (types/adapter.d.ts).
 *
 * Имя с префиксом — по необходимости: файлы адаптеров не являются модулями, поэтому
 * при allowJs все typedef-имена попадают в одну общую область (одноимённые → TS2300).
 * @typedef {import('../types/adapter').ExtractedMessage} ChatGPTExtractedMessage
 */

/**
 * Локализованная подпись ассистента. ChatGPT рендерит её СКРЫТЫМ заголовком
 * `<h4 class="sr-only …">` внутри блока ответа: визуально его нет, но textContent его
 * видит, и подпись утекает в начало content (ru «ChatGPT сказал:», en «ChatGPT said:»,
 * de «ChatGPT sagte:»). Срезается ТОЛЬКО в начале строки — иначе подпись внутри ответа
 * была бы испорчена. Проверено на снимке 2026-10-13: 5 из 5 assistant-реплик.
 */
const CHATGPT_ANSWER_PREFIX_RE = /^\s*(?:ChatGPT сказал|ChatGPT said|ChatGPT sagte):\s*/;

class ChatGPTAdapter extends BaseAdapter {
  constructor() {
    super();
    this.siteName = 'chatgpt';

    // ===== TURN-BASED ОТБОР (диагностика 2026-10-13, 3 раунда, живой DOM chatgpt.com) =====
    // Снимок 2026-10-13 (длинный чат, ровно 5 пар): [data-turn-key] — 5 узлов, стабильный
    // UUID НА ХОД (не хеш содержимого). Внутри каждого хода:
    //   [class*="bg-user-message"] — реплика пользователя (5/5);
    //   [class*="block-"] (конкретно block-BQZwFn) — ответ (5/5; длины 2213/1372/1022/756/487).
    // Прежние селекторы (.markdown, assistant-message, model-response,
    // data-message-author-role, data-virtualized-turn-content) на том же DOM дали 0
    // совпадений — поэтому отбор идёт ОТ ХОДА, а не от класса содержимого.
    // Класс block-BQZwFn — Tailwind JIT и сменится при пересборке сайта: буквально он НЕ
    // пинится. Уровни отбора по приоритету: 1) [class*="block-"]/[class*="content-"] внутри
    // хода; 2) структурный (самый длинный текстовый узел хода после реплики); 3) хвост/
    // виртуализация (bg-user-message БЕЗ data-turn-key); 4) легаси (.markdown/pre-wrap).
    this._turnSelectors = ['[data-turn-key]'];
    this._userSelectors = ['[class*="bg-user-message"]', '[class*="text-user-message"]'];
    this._assistantSelectors = ['[class*="block-"]', '[class*="content-"]'];

    // Те же маркеры реплики пользователя, но без обёртки атрибута: нужны для проверки
    // className узла и его предков (живой снимок 2026-10-13).
    this._userRoleMarkers = ['bg-user-message', 'text-user-message'];
    // Наследие старых сборок: маркер пузыря пользователя из исходной версии и признаки
    // контейнера ответа. Нужны ТОЛЬКО легаси-слою (_detectRole), отбор хода их не знает.
    this._legacyUserRoleMarkers = ['user-message-bubble-color'];
    this._assistantRoleMarkers = ['markdown', 'assistant-message', 'model-response'];

    // Легаси-селекторы содержимого (уровень 4, «старые сборки»). Имя поля прежнее: оно
    // читается снаружи адаптера, переименование сломало бы внешние ссылки.
    this.allContentSelectors = '.whitespace-pre-wrap, .markdown';

    // Счётчики последнего отбора. Наружу не торчат и считаются ВСЕГДА (они — часть
    // возврата _findMessageElements), а печатает их extractMessages только под гейтом.
    /** @type {{turns: number, users: number, assistants: number, skippedUnknown: number, looseUsers: number}} */
    this._lastTurnStats = { turns: 0, users: 0, assistants: 0, skippedUnknown: 0, looseUsers: 0 };
  }

  /**
   * Есть ли в className узла хоть один из маркеров (подстрока — как в исходной версии:
   * хеш-суффиксы Tailwind являются частью того же класса-токена).
   * @param {string} className
   * @param {string[]} markers
   * @returns {boolean}
   */
  _markerHit(className, markers) {
    const cls = String(className || '');
    if (!cls) return false;
    for (let i = 0; i < markers.length; i++) {
      if (cls.indexOf(markers[i]) !== -1) return true;
    }
    return false;
  }

  /**
   * Несёт ли узел маркер реплики пользователя — сам, на предке до 5 уровней вверх
   * (в исходной версии маркер жил именно на предке) или внутри своего поддерева.
   * Служит и определению роли, и ИСКЛЮЧЕНИЮ обёрток: узел, внутри которого лежит
   * реплика пользователя, ответом быть не может (иначе в ответ попал бы и вопрос).
   * @param {Element} element
   * @returns {boolean}
   */
  _hasUserMarker(element) {
    if (!element) return false;
    if (this._markerHit(element.className, this._userRoleMarkers)) return true;
    if (this._markerHit(element.className, this._legacyUserRoleMarkers)) return true;
    let parent = element.parentElement;
    for (let i = 0; i < 5 && parent; i++) {
      if (this._markerHit(parent.className, this._userRoleMarkers)) return true;
      if (this._markerHit(parent.className, this._legacyUserRoleMarkers)) return true;
      parent = parent.parentElement;
    }
    if (element.querySelector && element.querySelector(this._userSelectors.join(', '))) return true;
    return false;
  }

  /**
   * Первая непустая реплика пользователя внутри узла. Кандидаты — по порядку
   * `_userSelectors`: первый непустой набор выигрывает (форма донора qwen-adapter.js).
   * @param {Document|Element} scope
   * @returns {Element|null}
   */
  _firstUserNode(scope) {
    for (let i = 0; i < this._userSelectors.length; i++) {
      const found = scope.querySelectorAll(this._userSelectors[i]);
      for (let j = 0; j < found.length; j++) {
        if (String(found[j].textContent || '').trim()) return found[j];
      }
    }
    return null;
  }

  /**
   * Структурный фолбэк: самый длинный текстовый узел поддерева, не являющийся репликой
   * пользователя и не содержащий её.
   * @param {Element} scope
   * @param {Element|null} userEl
   * @returns {Element|null}
   */
  _longestTextNode(scope, userEl) {
    const nodes = scope.querySelectorAll('*');
    let best = null;
    let bestLen = 0;
    for (let i = 0; i < nodes.length; i++) {
      const node = nodes[i];
      if (node === userEl) continue;
      if (userEl && node.contains(userEl)) continue;
      if (this._hasUserMarker(node)) continue;
      // Дешёвый предфильтр по сырому textContent: _extractText (клон + обход) зовём
      // только для кандидата, который реально может выиграть.
      if (String(node.textContent || '').trim().length <= bestLen) continue;
      const text = this._extractText(node);
      if (text.length > bestLen) { best = node; bestLen = text.length; }
    }
    return best;
  }

  /**
   * Узел ответа внутри хода. Уровень 1 — класс-контейнер ответа ([class*="block-"] /
   * [class*="content-"]) вне реплики пользователя; выигрывает самый ДЛИННЫЙ текст (у
   * Tailwind-классов длина хеш-суффикса меняется, поэтому «первый» кандидат нестабилен).
   * Уровень 2 (структурный) — самый длинный текстовый узел хода ПОСЛЕ реплики; он
   * включается, только если реплика пользователя найдена (иначе роль ответа угадывалась
   * бы длиной, а это тот же дефект, что и нормализация 'unknown' → 'user').
   * @param {Element} turn
   * @param {Element|null} userEl
   * @returns {Element|null}
   */
  _assistantInTurn(turn, userEl) {
    let best = null;
    let bestLen = 0;
    for (let i = 0; i < this._assistantSelectors.length; i++) {
      const found = turn.querySelectorAll(this._assistantSelectors[i]);
      for (let j = 0; j < found.length; j++) {
        const node = found[j];
        if (node === userEl) continue;
        if (this._hasUserMarker(node)) continue;
        if (String(node.textContent || '').trim().length <= bestLen) continue;
        const text = this._extractText(node);
        if (text.length > bestLen) { best = node; bestLen = text.length; }
      }
    }
    if (best) return best;
    if (!userEl) return null;
    return this._longestTextNode(turn, userEl);
  }

  /**
   * Узлы сообщений в порядке чтения — по ОДНОЙ записи с ролью на реплику.
   * Уровни 1-2: для каждого хода [data-turn-key] — user (первая непустая) и assistant.
   * Уровень 3: реплики пользователя БЕЗ хода (хвост/виртуализация), ответ — следующий
   * sibling с непустым текстом. Уровень 4 (легаси, .markdown/pre-wrap) — ПОСЛЕДНИМ и
   * только если живой отбор не дал ничего: на новых сборках он дал бы дубли.
   * Роль 'unknown' в результат НЕ попадает — исходная нормализация 'unknown' → 'user'
   * и была корнем дефекта (ответ записывался в базу как реплика пользователя).
   * @returns {{role: string, element: Element}[]}
   */
  _findMessageElements() {
    /** @type {{role: string, element: Element}[]} */
    const found = [];
    const stats = { turns: 0, users: 0, assistants: 0, skippedUnknown: 0, looseUsers: 0 };

    const turnNodes = document.querySelectorAll(this._turnSelectors[0]);
    for (let i = 0; i < turnNodes.length; i++) {
      const turn = turnNodes[i];
      stats.turns++;
      const userEl = this._firstUserNode(turn);
      if (userEl) {
        found.push({ role: 'user', element: userEl });
        stats.users++;
      }
      const assistantEl = this._assistantInTurn(turn, userEl);
      if (assistantEl) {
        found.push({ role: 'assistant', element: assistantEl });
        stats.assistants++;
      }
    }

    const userSel = this._userSelectors.join(', ');
    const loose = document.querySelectorAll(userSel);
    for (let i = 0; i < loose.length; i++) {
      const el = loose[i];
      if (el.closest(this._turnSelectors[0])) continue; // уже разобрано уровнями 1-2
      if (el.parentElement && el.parentElement.closest(userSel)) continue; // вложенный маркер
      found.push({ role: 'user', element: el });
      stats.users++;
      stats.looseUsers++;
      let sib = el.nextElementSibling;
      while (sib) {
        if (String(sib.textContent || '').trim()) {
          found.push({ role: 'assistant', element: sib });
          stats.assistants++;
          break;
        }
        sib = sib.nextElementSibling;
      }
    }

    if (found.length === 0) {
      const legacy = document.querySelectorAll(this.allContentSelectors);
      for (let i = 0; i < legacy.length; i++) {
        const role = this._detectRole(legacy[i]);
        if (role === 'unknown') { stats.skippedUnknown++; continue; }
        found.push({ role: role, element: legacy[i] });
        if (role === 'user') stats.users++; else stats.assistants++;
      }
    }

    this._lastTurnStats = stats;
    return found;
  }

  /**
   * Роль узла по классу самого узла и класса предков (до 5 уровней вверх) — ЛЕГАСИ-слой
   * (уровень 4), на живой разметке 2026-10-13 не используется.
   *
   * Возвращаем string, а не литеральный union 'user'|'assistant': пока тип узкий, tsc
   * (TS2367) счёл бы сверку `role === 'unknown'` в extractMessages заведомо ложной, а она —
   * живой детектор дрейфа разметки. TODO: уточнить тип в шаге 5 (контракт ролей адаптера).
   * @param {Element} element
   * @returns {string}
   */
  _detectRole(element) {
    const classAttr = String(element.className || '');
    // Порядок исходной версии сохранён: markdown-рендер — ответ ассистента.
    if (classAttr.indexOf('markdown') !== -1) return 'assistant';
    // Живой маркер реплики пользователя (снимок 2026-10-13) — на узле или на предке.
    if (this._hasUserMarker(element)) return 'user';
    if (this._markerHit(classAttr, this._assistantRoleMarkers)) return 'assistant';
    // Роль НЕ определена. Это НЕ 'user': нормализация 'unknown' → 'user' в исходной версии
    // записывала ответ ассистента в базу как реплику пользователя. Узел пропускается.
    return 'unknown';
  }

  /**
   * Текст блочного узла с сохранением переводов строк: границы блочных элементов
   * (p/div/li/…, <br>) становятся `\n`, серии пустых строк схлопываются до одной пары.
   * Заменяет `clone.textContent`, который склеивал абзацы БЕЗ разделителя («первыйвторой»)
   * и тем самым ломал формат многострочного ответа. trim — только на краях результата:
   * значимые переводы строк ВНУТРИ текста сохраняются.
   * @param {Element} root
   * @returns {string}
   */
  _blockText(root) {
    let out = '';
    const BLOCK = {
      P: 1, DIV: 1, LI: 1, TR: 1, SECTION: 1, ARTICLE: 1, HEADER: 1, FOOTER: 1, MAIN: 1,
      H1: 1, H2: 1, H3: 1, H4: 1, H5: 1, H6: 1, PRE: 1, BLOCKQUOTE: 1, TABLE: 1, UL: 1, OL: 1
    };
    const walk = (node) => {
      if (node.nodeType === 3) { out += String(node.nodeValue || ''); return; }
      if (node.nodeType !== 1) return; // комментарии и прочее в текст не входят
      const tag = node.tagName;
      if (tag === 'BR') { out += '\n'; return; }
      const isBlock = BLOCK[tag] === 1;
      if (isBlock && out && out.charAt(out.length - 1) !== '\n') out += '\n';
      const kids = node.childNodes;
      for (let i = 0; i < kids.length; i++) walk(kids[i]);
      if (isBlock && out && out.charAt(out.length - 1) !== '\n') out += '\n';
    };
    walk(root);
    return out.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  }

  /**
   * Текст хода. markdown-рендер (легаси-разметка) — абзацы построчно. Иначе — клон без
   * кнопок/svg (как в исходной версии) и структурная нормализация блочных границ.
   * @param {Element} element
   * @returns {string}
   */
  _extractText(element) {
    const classAttr = String(element.className || '');
    if (classAttr.indexOf('markdown') !== -1) {
      const paragraphs = element.querySelectorAll('p');
      if (paragraphs.length > 0) {
        const lines = [];
        for (let i = 0; i < paragraphs.length; i++) {
          // Внутренний trim абзаца значим: он и есть «построчность» markdown-рендера.
          lines.push(String(paragraphs[i].textContent || '').trim());
        }
        return lines.join('\n').trim();
      }
    }
    const clone = /** @type {Element} */ (element.cloneNode(true));
    clone.querySelectorAll('button, [role="button"], svg').forEach(el => el.remove());
    return this._blockText(clone);
  }

  /**
   * Ходы диалога из DOM. Роли берутся из структуры хода (turn-based), пустые тексты
   * отбрасываются, а роль 'unknown' (легаси-узел не опознан) ПРОПУСКАЕТСЯ: нормализации
   * 'unknown' → 'user' больше нет — это и был корень дефекта. Диагностика — ТОЛЬКО под
   * гейтом (typeof-гард: в срез-песочницах тестов хелперов гейта может не быть).
   * @returns {ChatGPTExtractedMessage[]}
   */
  extractMessages() {
    const diagOn = (typeof aiCmDiagOn === 'function') ? aiCmDiagOn() : false;
    const elements = this._findMessageElements();
    /** @type {ChatGPTExtractedMessage[]} */
    const messages = [];
    for (let i = 0; i < elements.length; i++) {
      const role = elements[i].role;
      // Срез подписи — ЗДЕСЬ, а не в _extractText: тот же _extractText зовётся при ОТБОРЕ
      // узла по длине (см. _longestTextNode и _assistantInTurn), и срез сместил бы выбор
      // самого длинного узла, то есть подменил бы разметку, а не только текст.
      const content = this._extractText(elements[i].element).replace(CHATGPT_ANSWER_PREFIX_RE, '');
      if (!content || content.length === 0) continue;
      // Зеркало предиката _findMessageElements — детектор дрейфа разметки: сейчас 'unknown'
      // сюда не доходит (узел отсечён в легаси-слое), но конъюнкт не должен «умереть».
      if (role === 'unknown') continue;
      messages.push({ role: role, content: content });
    }
    if (diagOn && typeof aiCmDiagLine === 'function') {
      const stats = this._lastTurnStats;
      aiCmDiagLine('chatgpt-adapter-turn', {
        turns: stats.turns,
        users: stats.users,
        assistants: stats.assistants,
        msgs: messages.length,
        loose: stats.looseUsers,
        skippedUnknown: stats.skippedUnknown
      });
      // Ходы есть, а ответа нет — самый дорогой случай: разметку ответа пересобрали и все
      // уровни отбора мимо. Печатается один раз на вызов extractMessages (антиспам не нужен:
      // вызов идёт по циклу оценки токенов, но под гейтом строки и должны быть видны).
      if (stats.turns > 0 && stats.assistants === 0) {
        aiCmDiagLine('chatgpt-roles-miss', {
          turns: stats.turns,
          users: stats.users,
          turnSel: this._turnSelectors.join(', '),
          userSel: this._userSelectors.join(', '),
          assistantSel: this._assistantSelectors.join(', ')
        });
      }
    }
    return messages;
  }

  /**
   * Полный текст диалога: содержимое ходов, склеенное переводом строки.
   * Явное переопределение базового (у ChatGPT свой путь отбора узлов).
   * @returns {string}
   */
  getFullDialogText() {
    const messages = this.extractMessages();
    return messages.map(msg => msg.content).join('\n');
  }

  /**
   * Находимся ли мы на странице диалога: есть ход ([data-turn-key]) либо реплика
   * пользователя (в т.ч. хвост без атрибута) либо легаси-узел содержимого.
   * @returns {boolean}
   */
  isOnDialogPage() {
    if (document.querySelector(this._turnSelectors.join(', '))) return true;
    if (document.querySelector(this._userSelectors.join(', '))) return true;
    return document.querySelector(this.allContentSelectors) !== null;
  }

  // Честный детектор модели из DOM (второй слой; первый — model_slug из сети в content.js).
  // Ищет имя модели в шапке/селекторе. Если шапка показывает только бренд ("ChatGPT")
  // без версии — возвращает null (НЕ захардкоженное 'gpt-4o'), чтобы content.js взял
  // дефолт/сеть. Лог один раз, без спама. Безопасно (try/catch).
  /**
   * Имя модели из шапки/селектора; если шапка показывает только бренд — null
   * (не захардкоженное имя), иначе модель возьмётся из сети/дефолта.
   * @returns {string|null}
   */
  detectModel() {
    if (this._modelDetectLogged === undefined) this._modelDetectLogged = false;
    let found = null;
    try {
      const re = /(GPT-[\w.\-]+|Gemini[\s\d.\-A-Za-z]*|DeepSeek[\s\-A-Za-z0-9]*|Claude[\s\d.\-A-Za-z]*|o[134]-[\w.\-]*)/i;
      const selectors = [
        '[data-testid="model-switcher-dropdown-button"]',
        '[data-testid="model-switcher"]',
        'button[aria-label*="model" i]',
        'button[aria-label*="модель" i]',
        'nav button',
        'header button'
      ];
      for (let i = 0; i < selectors.length && !found; i++) {
        // innerText есть только у HTMLElement, а querySelectorAll по строке даёт Element
        // (TS2339). Уточняем форму узла: селекторы здесь кнопки/ссылки шапки.
        const els = /** @type {NodeListOf<HTMLElement>} */ (document.querySelectorAll(selectors[i]));
        for (let j = 0; j < els.length; j++) {
          const txt = (els[j].innerText || els[j].textContent || '').trim();
          const m = txt.match(re);
          if (m) { found = m[1]; break; }
        }
      }
      if (!found) {
        const labeled = document.querySelectorAll('[aria-label],[title]');
        for (let k = 0; k < labeled.length; k++) {
          const s = (labeled[k].getAttribute('aria-label') || '') + ' ' + (labeled[k].getAttribute('title') || '');
          const m2 = s.match(re);
          if (m2) { found = m2[1]; break; }
        }
      }
    } catch (e) { swallowSoft(e, 'adapter:chatgpt:detectModel'); /* никогда не ломаем сайт */ }
    if (!this._modelDetectLogged) {
      this._modelDetectLogged = true;
      debugLog('log', '[model-detect][DOM] ' + (found ? ('найдено в шапке: "' + found + '"') : 'имя модели в шапке не найдено (шапка показывает бренд — модель возьмётся из сети/дефолта)'));
    }
    return found; // null, если не нашли — это нормально
  }
}

/* ==== adapters/gemini-adapter.js ==== */
/**
 * Адаптер для Gemini (gemini.google.com).
 *
 * Типизация (шаг 4 Фазы 1): формы — из types/adapter.d.ts. Литеральный `import type`
 * невозможен (файл — классический скрипт контента плюс склейка исходника в
 * new Function() песочницами тестов), поэтому типы подключены JSDoc-ссылкой import().
 */

/**
 * Сообщение в форме адаптера (types/adapter.d.ts).
 *
 * Имя с префиксом сайта — НЕ по вкусу, а по необходимости: файлы адаптеров не
 * являются модулями (обычные скрипты, склеиваемые исходником), поэтому при allowJs
 * все typedef-имена попадают в одну общую область и одноимённые дают TS2300.
 * Настоящее имя типа хранится в types/adapter.d.ts, здесь только ссылка на него.
 * @typedef {import('../types/adapter').ExtractedMessage} GeminiExtractedMessage
 */

class GeminiAdapter extends BaseAdapter {
  constructor() {
    super();
    this.siteName = 'gemini';
    this.defaultModel = 'Gemini 2.5 Pro';
    debugLog('log', '[GeminiAdapter] Инициализирован');
  }

  /**
   * Находимся ли мы на диалоге (контейнер диалога ИЛИ поле ввода).
   * @returns {boolean}
   */
  isOnDialogPage() {
    try {
      const hasMessages = document.querySelector('.conversation-container') !== null;
      const hasInput = document.querySelector('rich-textarea, .input-area') !== null;
      const result = hasMessages || hasInput;
      debugLog('log', `[GeminiAdapter] isOnDialogPage: ${result}`);
      return result;
    } catch (error) {
      debugLog('error', '[GeminiAdapter] Ошибка в isOnDialogPage:', error);
      return false;
    }
  }

  /**
   * Ходы диалога: сперва по turn-контейнерам, при пустом результате — общий запасной
   * отбор по классам/дата-атрибутам роли. При ошибке — пустой массив.
   * @returns {GeminiExtractedMessage[]}
   */
  extractMessages() {
    try {
      /** @type {GeminiExtractedMessage[]} */
      const messages = [];

      const turnContainers = document.querySelectorAll('turn-container, .turn-container, [data-turn]');

      debugLog('log', `[GeminiAdapter] Найдено turn-контейнеров: ${turnContainers.length}`);

      if (turnContainers.length > 0) {
        turnContainers.forEach((turn, index) => {
          try {
            const userMessage = turn.querySelector('.user-query, [data-role="user"], .user-turn .query-text');
            if (userMessage) {
              const content = this._cleanText(userMessage.textContent);
              if (content.length > 0) {
                messages.push({ role: 'user', content });
              }
            }

            const assistantMessage = turn.querySelector('.model-response, [data-role="model"], .response-content, .assistant-turn .markdown');
            if (assistantMessage) {
              const content = this._cleanText(assistantMessage.textContent);
              if (content.length > 0) {
                messages.push({ role: 'assistant', content });
              }
            }
          } catch (turnError) {
            debugLog('error', `[GeminiAdapter] Ошибка обработки turn #${index}:`, turnError);
          }
        });
      }

      if (messages.length === 0) {
        debugLog('log', '[GeminiAdapter] Использую запасной метод поиска сообщений');

        const userMessages = document.querySelectorAll('.user-query, .query-text, [data-role="user"]');
        userMessages.forEach(msg => {
          const content = this._cleanText(msg.textContent);
          if (content.length > 0) {
            messages.push({ role: 'user', content });
          }
        });

        const assistantMessages = document.querySelectorAll('.model-response, .response-content, [data-role="model"]');
        assistantMessages.forEach(msg => {
          const content = this._cleanText(msg.textContent);
          if (content.length > 0) {
            messages.push({ role: 'assistant', content });
          }
        });
      }

      debugLog('log', `[GeminiAdapter] Всего извлечено сообщений: ${messages.length}`);
      return messages;

    } catch (error) {
      debugLog('error', '[GeminiAdapter] Ошибка в extractMessages:', error);
      return [];
    }
  }

  /**
   * Модель: из DOM (.model-name и т.п.), затем localStorage, затем this.defaultModel.
   * @returns {string}
   */
  detectModel() {
    try {
      const modelIndicator = document.querySelector('.model-name, .current-model, [aria-label*="model"]');

      if (modelIndicator) {
        const modelText = modelIndicator.textContent.trim();
        debugLog('log', `[GeminiAdapter] Обнаружена модель: ${modelText}`);
        return modelText || this.defaultModel;
      }

      const savedModel = localStorage.getItem('gemini-selected-model');
      if (savedModel) {
        debugLog('log', `[GeminiAdapter] Модель из localStorage: ${savedModel}`);
        return savedModel;
      }

      debugLog('log', `[GeminiAdapter] Использую модель по умолчанию: ${this.defaultModel}`);
      return this.defaultModel;

    } catch (error) {
      debugLog('error', '[GeminiAdapter] Ошибка в detectModel:', error);
      return this.defaultModel;
    }
  }

  /**
   * Нормализация текста хода (схлопывание пробелов и пустых строк).
   * @param {string} text
   * @returns {string}
   */
  _cleanText(text) {
    if (!text) return '';
    return text
      .replace(/\s+/g, ' ')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }
}

/* ==== adapters/aistudio-adapter.js ==== */
/**
 * Адаптер для Google AI Studio (aistudio.google.com).
 *
 * Почему отдельный класс, а не ветка GeminiAdapter: разметка реплик у AI Studio
 * другая. Ходы диалога — это <ms-cmark-node class="cmark-node v3-font-body">,
 * роль закодирована классом `user-chunk` у реплики пользователя (у ответа модели
 * этого класса нет). Селекторы Gemini (.conversation-container, turn-container,
 * .user-query, .model-response) на этой странице не находятся, поэтому штатный
 * GeminiAdapter извлекал 0 сообщений — бейдж токенов молчал.
 *
 * Наследование от GeminiAdapter даёт контракт BaseAdapter и общую нормализацию
 * текста (_cleanText); переопределено только то, что у AI Studio другое.
 *
 * Типизация (шаг 4 Фазы 1): формы — из types/adapter.d.ts. Литеральный `import type`
 * невозможен (файл — классический скрипт контента плюс склейка исходника в
 * new Function() песочницами тестов), поэтому типы подключены JSDoc-ссылкой import().
 */

/**
 * Имя с префиксом сайта — по необходимости: файлы адаптеров не являются модулями,
 * поэтому при allowJs все typedef-имена попадают в одну общую область.
 * @typedef {import('../types/adapter').ExtractedMessage} AistudioExtractedMessage
 */

class AistudioAdapter extends GeminiAdapter {
  constructor() {
    super();
    this.siteName = 'aistudio';
    this.defaultModel = 'gemini-3.1-pro';
    debugLog('log', '[AistudioAdapter] Инициализирован');
  }

  /**
   * Находимся ли мы на диалоге: признак — узлы реплик ms-cmark-node.
   * @returns {boolean}
   */
  isOnDialogPage() {
    try {
      const hasMessageNodes = document.querySelector('ms-cmark-node') !== null;
      debugLog('log', `[AistudioAdapter] isOnDialogPage: ${hasMessageNodes}`);
      if (hasMessageNodes) return true;
      // Виртуализированная лента: DOM может быть пуст, пока сеть уже отдала историю
      // ($rpc UpdatePrompt/Create → core/aistudio-intercept.js). Без этой ветки
      // processAndSend выходил по «не диалог» и бейдж молчал.
      const netCount = this._netMessages().length;
      if (netCount > 0) {
        debugLog('log', `[AistudioAdapter] isOnDialogPage: true (сеть: ${netCount} сообщений)`);
        return true;
      }
      return false;
    } catch (error) {
      debugLog('error', '[AistudioAdapter] Ошибка в isOnDialogPage:', error);
      return false;
    }
  }

  /**
   * Ходы диалога: все ms-cmark-node.v3-font-body, кроме вложенных в другой
   * ms-cmark-node (иначе текст реплики попал бы в счёт дважды — родитель и ребёнок).
   * Роль: класс user-chunk → 'user', иначе — 'assistant'.
   * @returns {AistudioExtractedMessage[]}
   */
  extractMessages() {
    try {
      // Сеть главнее DOM: полная история из $rpc (включая виртуализированные ходы).
      // DOM остаётся фолбэком — как у Claude/Perplexity, где сеть и есть источник.
      const netMessages = this._netMessages();
      if (netMessages.length > 0) {
        debugLog('log', `[AistudioAdapter] История из сети: ${netMessages.length} сообщений (DOM не читаем)`);
        return netMessages;
      }

      /** @type {AistudioExtractedMessage[]} */
      const messages = [];

      const nodes = document.querySelectorAll('ms-cmark-node.v3-font-body');

      debugLog('log', `[AistudioAdapter] Найдено узлов реплик: ${nodes.length}`);

      Array.prototype.forEach.call(nodes, (node, index) => {
        try {
          if (this._isNestedNode(node)) {
            debugLog('log', `[AistudioAdapter] Пропуск вложенного узла #${index}`);
            return;
          }

          const content = this._cleanText(this._readNodeText(node));
          if (content.length === 0) return;

          messages.push({ role: this._isUserChunk(node) ? 'user' : 'assistant', content });
        } catch (nodeError) {
          debugLog('error', `[AistudioAdapter] Ошибка обработки узла #${index}:`, nodeError);
        }
      });

      debugLog('log', `[AistudioAdapter] Всего извлечено сообщений: ${messages.length}`);
      return messages;

    } catch (error) {
      debugLog('error', '[AistudioAdapter] Ошибка в extractMessages:', error);
      return [];
    }
  }

  /**
   * Модель AI Studio (v2.0.32).
   *
   * ДО ЧЕГО БЫЛО: константа 'gemini-3.1-pro'. Бейдж называл её и после того, как студия
   * переключилась на 'Gemini 3.8 Flash' — расхождение с самой студией читается как дефект.
   *
   * ОТКУДА ТЕПЕРЬ. Тело запроса GenerateContent всегда несёт model: models/<slug>, поэтому
   * перехватчик (core/aistudio-intercept.js:modelFromBody) присылает его мостом
   * ai-cm-model-slug, а core/content.js кладёт в window.__aiCmNetModelSlug (ISOLATED-мир
   * один, отдельного канала не нужно) и в кэш истории — значит после F5 фолбэка в константу
   * уже не будет.
   *
   * ПОЧЕМУ НЕ DOM. Индикатор модели в панели Run settings не имеет стабильного класса, а
   * текстовая догадка по «Gemini <версия> <семейство>» ловила бы упоминания модели в самой
   * реплике и подписывала чат чужой моделью. Сеть — единственный недвусмысленный источник.
   * @returns {string}
   */
  detectModel() {
    try {
      const slug = (typeof window !== 'undefined') ? window.__aiCmNetModelSlug : '';
      if (typeof slug === 'string' && slug) {
        debugLog('log', `[AistudioAdapter] Модель из сети: ${slug}`);
        return slug;
      }
    } catch (error) {
      debugLog('error', '[AistudioAdapter] Ошибка чтения модели из сети:', error);
    }
    // Фолбэк прежний (ключ есть в utils/model-config.js, окно 128k): сеть ещё не говорила.
    return 'gemini-3.1-pro';
  }

  /**
   * Сетевая история AI Studio: снимок, который MAIN-перехватчик
   * (core/aistudio-intercept.js) положил в ISOLATED-мир через core/content.js
   * (window.__aiCmNetMsgs = { msgs: [{role, text}], count, ts, href }).
   *
   * Снимок принимается только для ТЕКУЩЕГО пути (SPA: AI Studio меняет /prompts/<id>
   * без перезагрузки) — иначе история прошлого разговора питала бы счётчик нового.
   * Нет снимка/путь не тот → [] и обычный DOM-парсинг.
   * @returns {AistudioExtractedMessage[]}
   */
  _netMessages() {
    try {
      const raw = (typeof window !== 'undefined') ? window.__aiCmNetMsgs : null;
      if (!raw || !Array.isArray(raw.msgs) || raw.msgs.length === 0) return [];
      const here = String((window.location && window.location.pathname) || '');
      const there = String(raw.href || '');
      if (there && typeof URL === 'function') {
        let therePath = there;
        try { therePath = new URL(there).pathname; } catch (eUrl) { therePath = there; }
        if (therePath && here && therePath !== here) return [];
      }
      /** @type {AistudioExtractedMessage[]} */
      const messages = [];
      Array.prototype.forEach.call(raw.msgs, (m) => {
        if (!m || typeof m.text !== 'string') return;
        const content = this._cleanText(m.text);
        if (content.length === 0) return;
        messages.push({ role: (m.role === 'assistant' || m.role === 'model') ? 'assistant' : 'user', content });
      });
      return messages;
    } catch (error) {
      debugLog('error', '[AistudioAdapter] Ошибка чтения сетевой истории:', error);
      return [];
    }
  }

  /**
   * Текст узла реплики. innerText предпочтителен (видимый текст, как в браузере);
   * textContent — фолбэк для окружений без innerText (jsdom, песочницы тестов).
   * @param {Element} node
   * @returns {string}
   */
  _readNodeText(node) {
    try {
      // innerText объявлен только у HTMLElement, а JSDoc-тип параметра — Element
      // (node приходит из querySelectorAll по ms-cmark-node): приводим тип, не меняя рантайм.
      const inner = (/** @type {HTMLElement} */ (node)).innerText;
      if (typeof inner === 'string' && inner.length > 0) return inner;
      return typeof node.textContent === 'string' ? node.textContent : '';
    } catch (error) {
      debugLog('error', '[AistudioAdapter] Ошибка чтения текста узла:', error);
      return '';
    }
  }

  /**
   * Вложенный ли узел: у него есть предок ms-cmark-node (текст уже учтён предком).
   * @param {Element} node
   * @returns {boolean}
   */
  _isNestedNode(node) {
    try {
      const parent = node && node.parentElement;
      if (!parent || typeof parent.closest !== 'function') return false;
      return parent.closest('ms-cmark-node') !== null;
    } catch (error) {
      debugLog('error', '[AistudioAdapter] Ошибка проверки вложенности:', error);
      return false;
    }
  }

  /**
   * Реплика пользователя? В AI Studio её единственный признак — класс user-chunk.
   * @param {Element} node
   * @returns {boolean}
   */
  _isUserChunk(node) {
    try {
      return !!(node && node.classList && node.classList.contains('user-chunk'));
    } catch (error) {
      debugLog('error', '[AistudioAdapter] Ошибка чтения classList:', error);
      return false;
    }
  }
}

// Экспортируем для использования в других скриптах
if (typeof module !== 'undefined' && module.exports) {
  module.exports = AistudioAdapter;
}

/* ==== adapters/deepseek-adapter.js ==== */
/**
 * Адаптер для DeepSeek (chat.deepseek.com).
 *
 * Типизация (шаг 4 Фазы 1): формы — из types/adapter.d.ts. Литеральный `import type`
 * невозможен (файл — классический скрипт контента плюс склейка исходника в
 * new Function()/eval песочницами тестов), поэтому типы подключены JSDoc-ссылкой import().
 */

/**
 * Сообщение в форме адаптера (types/adapter.d.ts).
 *
 * Имя с префиксом — по необходимости: файлы адаптеров не являются модулями, поэтому
 * при allowJs все typedef-имена попадают в одну общую область (одноимённые → TS2300).
 * @typedef {import('../types/adapter').ExtractedMessage} DeepSeekExtractedMessage
 */

class DeepSeekAdapter extends BaseAdapter {
  constructor() {
    super();
    this.siteName = 'deepseek';
    debugLog('log', '[DeepSeekAdapter] Инициализирован');
  }

  /**
 * Находимся ли мы на странице диалога: есть узлы ds-message ИЛИ поле ввода.
 * @returns {boolean}
 */
isOnDialogPage() {
    const hasMessages = document.querySelectorAll('div[class*="ds-message"]').length > 0;
    const hasInput = document.querySelector('textarea') !== null;
    return hasMessages || hasInput;
  }

  // loadFullHistory удалён в v1.1 — скролл-пагинация противоречит архитектуре server-first
  // (основной источник данных — перехват сети). Метод не вызывался ни из одного файла.

  // ===== v2 (O-15): reasoning DeepSeek — ЧАСТЬ assistant-хода, а не отдельное сообщение =====
  // Панель размышлений в DOM живёт отдельным узлом с классом ds-message* — в живом прогоне
  // это давало «Извлечено 2 сообщений, роли: assi, assi»: пузыри пользователя отбрасывались
  // (роль 'unknown'), а reasoning и ответ уходили двумя assistant-сообщениями (пара
  // user→assistant рвалась, а «.» свёрнутой панели попадала в текст хода как [ANSWER]).
  // Классы DeepSeek ротируются, поэтому признак — комбинация: маркер reasoning + ОТСУТСТВИЕ
  // markdown-рендера ответа (.ds-markdown) внутри узла.
  /** Селекторы узлов панели размышлений (thinking) — классы DeepSeek ротируются. */
  _thinkSelector() {
    return '[class*="ds-think"], [class*="think-content"], [class*="ds-reason"], [data-testid*="think"]';
  }
  /**
   * Признак панели размышлений: класс узла, вложенный think-узел либо маркер в начале текста.
   * @param {Element} element
   * @returns {boolean}
   */
  _hasThinkMarker(element) {
    try {
      if (!element) return false;
      const cls = String(element.className || '');
      if (/ds-think|think-content|ds-reason/i.test(cls)) return true;
      if (typeof element.querySelector === 'function' && element.querySelector(this._thinkSelector())) return true;
      const txt = String(element.textContent || '').trim();
      return /^(?:deepthink|deep\s*think|thought|thinking|размышлен|думаю|思考)/i.test(txt);
    } catch (e) { return false; }
  }
  /**
   * Узел markdown-рендера ответа (сам узел либо вложенный .ds-markdown), иначе null.
   * @param {Element} element
   * @returns {Element|null}
   */
  _answerMarkdown(element) {
    try {
      if (!element) return null;
      if (String(element.className || '').includes('ds-markdown')) return element;
      const md = (typeof element.querySelector === 'function') ? element.querySelector('.ds-markdown') : null;
      return md || null;
    } catch (e) { return null; }
  }
  // Узел — ТОЛЬКО панель размышлений (ответа в нём нет): сообщением хода не является.
  /**
   * Узел — только панель размышлений (ответа в нём нет): сообщением хода не является.
   * @param {Element} element
   * @returns {boolean}
   */
  _isReasoningOnly(element) {
    try {
      if (!element) return false;
      if (this._answerMarkdown(element)) return false;
      return this._hasThinkMarker(element);
    } catch (e) { return false; }
  }
  /**
   * Находится ли узел внутри панели размышлений (сам think-класс либо ближайший think-предок).
   * @param {Element} element
   * @returns {boolean}
   */
  _isInsideReasoning(element) {
    try {
      if (!element) return false;
      if (/ds-think|think-content|ds-reason/i.test(String(element.className || ''))) return true;
      return (typeof element.closest === 'function') && !!element.closest(this._thinkSelector());
    } catch (e) { return false; }
  }
  /**
   * Текст элемента БЕЗ панелей размышлений и служебных кнопок/иконок.
   * @param {Element} element
   * @returns {string}
   */
  _textWithoutReasoning(element) {
    try {
      const clone = /** @type {Element} */ (element.cloneNode(true));
      Array.prototype.slice.call(clone.querySelectorAll(this._thinkSelector())).forEach(el => el.remove());
      clone.querySelectorAll('button, svg, [class*="avatar"], [class*="icon"], [class*="toolbar"]')
        .forEach(el => el.remove());
      return clone.textContent.trim();
    } catch (e) { return ''; }
  }
  // ===== O-7 (hidden-захват): текст панели размышлений ОТДЕЛЬНЫМ полем =====
  // Базовый текст хода панель reasoning НЕ несёт (_textWithoutReasoning её вырезает,
  // _isReasoningOnly такие узлы вовсе пропускает) — в DOM-ветке reasoning исторически
  // терялся на ЗАХВАТЕ. Здесь он сохраняется рядом с текстом (hiddenReasoning) и НЕ
  // попадает ни в content, ни в метрики/токены: базовый текст байтово прежний, а в
  // экспорт блок уходит только при включённом тумблере aiCmIncludeHiddenInExport
  // (сырой режим, utils/export-emit-pipeline.js:includeHiddenExportBlocks).
  // Служебная шапка свёрнутой панели («DeepThink · 12 с», «Размышления:», «Thought for 3s») —
  /**
   * Снимает служебную шапку панели в начале текста («DeepThink · 12 с», «Размышления:»).
   * @param {string} text
   * @returns {string}
   */
  _stripReasoningHeader(text) {
    try {
      const s = String(text == null ? '' : text).trim();
      return s.replace(
        /^(?:deepthink|deep\s?think|thought|thinking|размышлен[а-яё]*|思考)\s*(?:[·:•\-–—]\s*\d+\s*(?:с|s|sec|сек|seconds?)?)?\s*[:·]?\s*/i,
        ''
      ).trim();
    } catch (e) { return String(text == null ? '' : text).trim(); }
  }
  /**
   * Текст панели размышлений узла (сама панель либо вложенные think-узлы),
   * склеенный пустой строкой; пустые/служебные части отброшены.
   * @param {Element} element
   * @returns {string}
   */
  _reasoningText(element) {
    try {
      if (!element) return '';
      /** @type {Node[]} */
      const nodes = [];
      if (this._isInsideReasoning(element)) {
        nodes.push(element);
      } else if (typeof element.querySelectorAll === 'function') {
        const found = element.querySelectorAll(this._thinkSelector());
        for (let i = 0; i < found.length; i++) nodes.push(found[i]);
      }
      const parts = [];
      for (let j = 0; j < nodes.length; j++) {
        const text = this._stripReasoningHeader(nodes[j].textContent);
        if (text && this._hasRealContent(text)) parts.push(text);
      }
      return parts.join('\n\n').trim();
    } catch (e) { return ''; }
  }
  // Артефакт интерфейса («.» свёрнутой панели) — не сообщение: в сообщении должна быть
  // хотя бы одна буква или цифра. Формат текста при этом не трогаем.
  /**
   * Есть ли в тексте реальные символы (буква/цифра), а не только артефакт интерфейса
   * вроде «.» свёрнутой панели.
   * @param {string} text
   * @returns {boolean}
   */
  _hasRealContent(text) {
    return /[0-9A-Za-z\u00C0-\u024F\u0400-\u04FF\u4E00-\u9FFF]/.test(String(text == null ? '' : text));
  }
  /**
   * Первый дочерний узел с текстом, годный как текст хода (без avatar/button/icon,
   * без панелей размышлений), иначе null.
   * @param {Element} element
   * @returns {Element|null}
   */
  _firstContentChild(element) {
    try {
      const candidates = element.querySelectorAll(
        'div:not([class*="avatar"]):not([class*="button"]):not([class*="icon"])'
      );
      for (let i = 0; i < candidates.length; i++) {
        if (this._isInsideReasoning(candidates[i])) continue;
        return candidates[i];
      }
    } catch (e) { swallowSoft(e, 'adapter:deepseek:firstContentChild'); }
    return null;
  }

  /**
   * Роль хода по разметке узла.
   *
   * Возвращаем string, а не литеральный union 'user'|'assistant': пока тип узкий,
   * tsc (TS2367) считает проверки `role !== 'unknown'` в extractMessages
   * (строки 219 и 236) заведомо ложными. Эти проверки — НАМЕРЕННЫЙ детектор дрейфа
   * предиката (см. комментарий O-21 у них), и удалять их нельзя: они должны
   * «ожить», если _detectRole снова начнёт отдавать 'unknown'. Тип string оставляет
   * гейт живым и типизирует функцию честно — она отдаёт произвольную строку роли.
   * TODO: уточнить тип в шаге 5 (контракт ролей адаптера).
   * @param {Element} element
   * @returns {string}
   */
  _detectRole(element) {
    const classes = element.className || '';
    if (classes.includes('d29f3d7d')) return 'user';
    if (classes.includes('ds-markdown') || classes.includes('ds-assistant-message')) return 'assistant';
    try {
      if (element.querySelector && element.querySelector('.ds-markdown, .ds-markdown-paragraph')) return 'assistant';
      if (this._isReasoningOnly(element)) return 'assistant';
    } catch (e) { swallow(e, 'adapter:deepseek:detectRole'); }
    // v2 (O-15): хеш-класс пузыря пользователя ротируется (d29f3d7d устарел), а роль
    // 'unknown' отбрасывалась в extractMessages — реплики пользователя исчезали из
    // live-экспорта. Не-assistant-подобный пузырь — реплика пользователя.
    return 'user';
  }

  /**
   * Текст хода: markdown-абзацы ответа построчно, иначе первый текстовый узел
   * пузыря без панелей размышлений.
   * @param {Element} element
   * @returns {string}
   */
  _extractText(element) {
    // Ответ ассистента — markdown-рендер (абзацы построчно; панель размышлений внутри
    // того же пузыря в текст не входит).
    const markdown = this._answerMarkdown(element);
    if (markdown) {
      const paragraphs = markdown.querySelectorAll('.ds-markdown-paragraph, p');
      if (paragraphs.length > 0) {
        return Array.from(paragraphs).map(p => p.textContent.trim()).filter(Boolean).join('\n');
      }
    }
    const textChild = this._firstContentChild(element);
    if (textChild) return this._textWithoutReasoning(textChild);
    return this._textWithoutReasoning(element);
  }

  /**
   * Ходы диалога из DOM (v2/O-15 + O-7 + O-21).
   *
   * Узлы-панели reasoning сообщениями НЕ являются: их текст переносится в
   * hiddenReasoning ближайшего assistant-хода (висячий — предыдущего, иначе
   * последнего). Возвращает пустой массив при ошибке.
   * @returns {DeepSeekExtractedMessage[]}
   */
  extractMessages() {
    try {
      /**
       * Накопленные ходы. Поля hiddenReasoning нет в контракте ExtractedMessage
       * (types/adapter.d.ts — форма {role, content}), поэтому элементы здесь
       * расширяют её на поле захвата reasoning.
       * @type {(DeepSeekExtractedMessage & {hiddenReasoning?: string})[]}
       */
      const messages = [];
      const messageElements = document.querySelectorAll('div[class*="ds-message"]');
      // ===== O-21 (ДИАГНОСТИКА, только измерение): усечение DOM-экстрактора DeepSeek =====
      // Живой симптом: под соседним расширением (Better DeepSeek) DOM отдавал msgs=3 при
      // сетевых msgs=6. Живые артефакты утеряны, механизм — неподтверждённая гипотеза,
      // поэтому здесь ТОЛЬКО счётчики и сэмплы: ни одна ветка extractMessages не меняется,
      // messages/роли/hiddenReasoning побайтово прежние. Гейт — канонический
      // utils/debug.js:aiCmDiagOn (sessionStorage 'aiCmDebug' === '1' ИЛИ чекбокс «Подробные
      // логи» → window.__aiCmDebugLogs). Гейт выключен → счётчики не считаются вовсе
      // (нулевой оверхед) и не печатается ни одной строки.
      // typeof-гарды — конвенция срез-песочниц тестов: адаптер грузится без utils/debug.js,
      // там хелперов нет → o21Stats === null → поведение прежнее 1:1.
      const o21DiagOn = (typeof aiCmDiagOn === 'function') ? aiCmDiagOn() : false;
      const o21Stats = o21DiagOn ? {
        totalFound: messageElements.length,
        extracted: 0,
        skippedNested: 0,
        skippedReasoningOnly: 0,
        skippedEmpty: 0,
        skippedUnknown: 0,
        skippedNoRealContent: 0,
        classesSample: [],
        neighborInjections: []
      } : null;
      if (o21Stats) {
        // Детекция инъекций соседа (Better DeepSeek): только наличие маркеров в первых 50 КБ
        // HTML документа. В текст/базу/экспорт значение не идёт — это измерение факта.
        try {
          const o21Markers = ['BetterDeepSeek', 'BDS:', 'better-deepseek', 'bds-'];
          const o21Root = (typeof document !== 'undefined') ? (document.documentElement || document.body) : null;
          const o21Html = o21Root ? String(o21Root.innerHTML || '').slice(0, 50000) : '';
          for (let m = 0; m < o21Markers.length; m++) {
            if (o21Html.indexOf(o21Markers[m]) !== -1) o21Stats.neighborInjections.push(o21Markers[m]);
          }
        } catch (eO21inj) { }
      }
      // O-7: «висячий» reasoning отдельного узла (assistant-узел только с THINK) — не
      // сообщение (v2/O-15), но его текст НЕ теряется: приклеивается к следующему
      // assistant-ходу, а если следующего нет — к предыдущему. Та же парность, что у
      // сетевого перехватчика (v9/O-15: pendingReasoning), и только в hiddenReasoning —
      // базовый текст/роли/состав сообщений не меняются.
      let pendingReasoning = '';
      messageElements.forEach((element, idx) => {
        // O-21: сэмпл классов первых трёх узлов — классы DeepSeek ротируются, сэмпл нужен,
        // чтобы по живому логу увидеть, что именно попало в выборку. Чтение, без записи.
        if (o21Stats && idx < 3) {
          o21Stats.classesSample.push(String(element.className || '').slice(0, 60));
        }
        if (element.className?.includes('ds-markdown') && element.parentElement?.className?.includes('ds-message')) {
          if (o21Stats) o21Stats.skippedNested++;
          return;
        }
        // v2 (O-15): панель reasoning — не сообщение хода (текст reasoning приходит
        // секцией [REASONING] из сетевого перехватчика вместе с ответом).
        if (this._isReasoningOnly(element)) {
          if (o21Stats) o21Stats.skippedReasoningOnly++;
          const orphanReasoning = this._reasoningText(element);
          if (orphanReasoning) {
            pendingReasoning = pendingReasoning ? (pendingReasoning + '\n\n' + orphanReasoning) : orphanReasoning;
          }
          return;
        }
        const role = this._detectRole(element);
        const content = this._extractText(element);
        if (content && content.length > 0 && role !== 'unknown' && this._hasRealContent(content)) {
          const msg = { role, content };
          // O-7: hidden-захват reasoning — рядом с текстом, в content НЕ входит.
          if (role === 'assistant') {
            const ownReasoning = this._reasoningText(element);
            const hiddenReasoning = [pendingReasoning, ownReasoning].filter(Boolean).join('\n\n').trim();
            if (hiddenReasoning) msg.hiddenReasoning = hiddenReasoning;
            pendingReasoning = '';
          }
          messages.push(msg);
          if (o21Stats) o21Stats.extracted++;
        } else if (o21Stats) {
          // O-21: причина пропуска — ПОВТОР предиката, только ради счётчика. Ветка недостижима
          // при true-предикате и ничего не делает с messages: поток не меняется. Конъюнкт
          // role !== 'unknown' оставлен зеркалом предиката (сейчас _detectRole 'unknown' не
          // возвращает — счётчик работает детектором дрейфа предиката).
          if (!content || content.length === 0) o21Stats.skippedEmpty++;
          else if (role === 'unknown') o21Stats.skippedUnknown++;
          else o21Stats.skippedNoRealContent++;
        }
      });
      // Висячий reasoning в конце ленты — к последнему assistant-ходу (отдельного хода нет).
      if (pendingReasoning) {
        for (let i = messages.length - 1; i >= 0; i--) {
          if (messages[i].role !== 'assistant') continue;
          messages[i].hiddenReasoning = messages[i].hiddenReasoning
            ? (messages[i].hiddenReasoning + '\n\n' + pendingReasoning)
            : pendingReasoning;
          break;
        }
      }
      if (messages.length > 0) {
        debugLog('log', `[DeepSeekAdapter] Извлечено ${messages.length} сообщений, роли: ${messages.map(m => m.role.substring(0, 4)).join(', ')}`);
      }
      // O-21: печать счётчиков каноническим хелпером utils/debug.js:aiCmDiagLine — тот же
      // гейт aiCmDebug, та же форма k=v, канон-префикс '[AI CM][diag] o21-dom-extract'.
      // Хелпера нет (срез-песочница тестов) → ни одной строки, поведение прежнее 1:1.
      if (o21Stats && typeof aiCmDiagLine === 'function') {
        try {
          aiCmDiagLine('o21-dom-extract', {
            site: this.siteName || 'deepseek',
            totalFound: o21Stats.totalFound,
            extracted: o21Stats.extracted,
            skipNested: o21Stats.skippedNested,
            skipReasoningOnly: o21Stats.skippedReasoningOnly,
            skipEmpty: o21Stats.skippedEmpty,
            skipUnknown: o21Stats.skippedUnknown,
            skipNoRealContent: o21Stats.skippedNoRealContent,
            classesSample: o21Stats.classesSample.join(' | ') || '(нет)',
            neighborInjections: o21Stats.neighborInjections.join(',') || '(нет)'
          });
        } catch (eO21line) { }
      }
      return messages;
    } catch (error) {
      debugLog('error', '[DeepSeekAdapter] Ошибка:', error);
      return [];
    }
  }

  /**
   * Полный текст диалога: содержимое ходов, склеенное переводом строки.
   * @returns {string}
   */
  getFullDialogText() {
    return this.extractMessages().map(msg => msg.content).join('\n');
  }

  /**
   * Модель: DeepThink (R1) по aria-pressed, затем UI-селекторы, затем localStorage,
   * иначе 'deepseek-v3'.
   * @returns {string}
   */
  detectModel() {
    try {
      // Проверяем активность DeepThink (R1) по aria-pressed
      const deepThinkBtn = document.querySelector(
        'div.ds-toggle-button[aria-pressed="true"], div[class*="toggle-button"][aria-pressed="true"]'
      );
      if (deepThinkBtn && deepThinkBtn.textContent.includes('DeepThink')) {
        debugLog('log', '[DeepSeekAdapter] DeepThink активен → R1');
        return 'deepseek-r1';
      }

      // Проверяем модель в интерфейсе
      const modelSelectors = [
        '.model-selector', '.current-model', '[class*="model-switch"]',
        '.model-name', 'select[name="model"]', '[aria-label*="model"]'
      ];
      for (const selector of modelSelectors) {
        const el = document.querySelector(selector);
        if (el) {
          // options/selectedIndex есть только у HTMLSelectElement, а querySelector
          // по строке даёт Element (TS2339). Тег уже проверен выше, поэтому
          // сужаем форму узла до SELECT — поведение рантайма не меняется.
          let text = el.tagName === 'SELECT'
            ? (/** @type {HTMLSelectElement} */ (el).options[/** @type {HTMLSelectElement} */ (el).selectedIndex]?.text || '')
            : el.textContent.trim();
          if (text) {
            debugLog('log', '[DeepSeekAdapter] Модель из UI:', text);
            if (text.toLowerCase().includes('r1')) return 'deepseek-r1';
            if (text.toLowerCase().includes('v3')) return 'deepseek-v3';
          }
        }
      }

      // Проверяем localStorage
      const savedModel = localStorage.getItem('deepseek-selected-model') ||
        localStorage.getItem('selected-model');
      if (savedModel) {
        debugLog('log', '[DeepSeekAdapter] Модель из localStorage:', savedModel);
        if (savedModel.toLowerCase().includes('r1')) return 'deepseek-r1';
        if (savedModel.toLowerCase().includes('v3')) return 'deepseek-v3';
      }

      return 'deepseek-v3';
    } catch (error) {
      debugLog('error', '[DeepSeekAdapter] Ошибка в detectModel:', error);
      return 'deepseek-v3';
    }
  }
}

/* ==== adapters/google-search-adapter.js ==== */
// ===== O-45: КОД-БЛОКИ (окна кода python/js) в DOM-пути адаптера =====
// Типизация (шаг 4 Фазы 1): формы — из types/adapter.d.ts. Литеральный `import type`
// невозможен (файл — классический скрипт контента плюс склейка исходника в
// new Function()/eval песочницами тестов), поэтому типы подключены JSDoc-ссылкой import().

/**
 * Сообщение в форме адаптера (types/adapter.d.ts).
 *
 * Имя с префиксом — по необходимости: файлы адаптеров не являются модулями, поэтому
 * при allowJs все typedef-имена попадают в одну общую область (одноимённые → TS2300).
 * @typedef {import('../types/adapter').ExtractedMessage} GoogleSearchExtractedMessage
 */

/**
 * Узлы ответа, которые вернёт парсер: ровно то, что later-код умеет обходить
 * (for по длине + gsaAnswerText от Element).
 * @typedef {NodeList|Element[]} GsaAnswerNodes
 */

// Единственный источник правды — utils/google-search-folwr-parser.js (renderCodeBlock /
// answerTextOf / answerDomNodes): сетевой путь, DOM-добор перехватчика и DOM-путь адаптера
// обязаны давать ОДИН и тот же текст по коду, поэтому собственных правил адаптер не держит
// (тот же паттерн ленивого резолва общего хелпера, что у Qwen-адаптера в O-37). Хелпер
// резолвится лениво, на каждом вызове:
//   1) общий ISOLATED-мир — window.GoogleFolwrUtils (парсер загружен в этот мир);
//   2) Node-путь (require) — тесты и Node-песочницы;
//   3) ничего из этого нет → поведение ровно как до O-45: .n6owBd.awi2gc + голый textContent.

/**
 * Используемая поверхность общего хелпера рендера ответов AI-режима
 * (в бою — window.GoogleFolwrUtils; см. строки проверок выше).
 * @typedef {object} GsaFolwrUtils
 * @property {function(Element): string} answerTextOf текст узла ответа общим рендером
 * @property {function(Document|Element): GsaAnswerNodes} answerDomNodes узлы ответа
 */

/**
 * Ленивый резолв общего хелпера рендера ответов AI-режима: общий мир, затем
 * Node-путь (require), иначе null.
 *
 * TODO: уточнить тип в шаге 5 (форма window.GoogleFolwrUtils без @types: сейчас
 * она any в types/globals.d.ts — здесь сузили до используемой поверхности).
 * @returns {GsaFolwrUtils|null}
 */
function gsaFolwrUtils() {
  try {
    if (typeof window !== 'undefined' && window.GoogleFolwrUtils &&
        typeof window.GoogleFolwrUtils.answerTextOf === 'function' &&
        typeof window.GoogleFolwrUtils.answerDomNodes === 'function') {
      return window.GoogleFolwrUtils;
    }
  } catch (e) { }
  try {
    if (typeof require === 'function') {
      var mod = require('../utils/google-search-folwr-parser.js');
      if (mod && typeof mod.answerTextOf === 'function' && typeof mod.answerDomNodes === 'function') {
        return mod;
      }
    }
  } catch (e2) { }
  return null;
}

// Текст узла ответа общим рендером парсера (код-окна → ```lang … ```); без хелпера — прежний
// textContent, то есть байты DOM-пути не меняются.
/**
 * Текст узла ответа общим рендером парсера (код-окна → ```lang … ```); без хелпера —
 * прежний textContent клона без script/style/button/svg.
 * @param {Element} el
 * @returns {string}
 */
function gsaAnswerText(el) {
  var util = gsaFolwrUtils();
  if (util) {
    try { return String(util.answerTextOf(el) || ''); } catch (e) { swallowSoft(e, 'adapter:google-search:answerText'); }
  }
  try {
    var clone = /** @type {Element} */ (el.cloneNode(true));
    clone.querySelectorAll('script, style, button, svg').forEach(function(n) { n.remove(); });
    return String(clone.textContent || '');
  } catch (e2) { return ''; }
}

/**
 * Узлы ответа общим отбором парсера (чанки прозы + самостоятельные код-окна между
 * ними); без хелпера — только чанки .n6owBd.awi2gc, как раньше.
 * @param {Document|Element} root
 * @returns {GsaAnswerNodes}
 */
function gsaAnswerNodes(root) {
  var util = gsaFolwrUtils();
  if (util) {
    try {
      var nodes = util.answerDomNodes(root);
      if (nodes) return nodes;
    } catch (e) { swallowSoft(e, 'adapter:google-search:answerNodes'); }
  }
  try { return root.querySelectorAll('.n6owBd.awi2gc'); } catch (e2) { return []; }
}

class GoogleSearchAdapter extends BaseAdapter {
  constructor() {
    super();
    this.siteName = 'google_search';
    this._lastNetworkModel = '';
    this._lastExtractedCount = null; // антиспам: последнее N в «Извлечено N сообщений»
    this._lastCodeBlockSig = null;   // O-45 (ДИАГНОСТИКА): антиспам строки структуры код-блока
    console.log('[GoogleSearchAdapter] Инициализирован (v2: AI-режим)');

    if (typeof window !== 'undefined') {
      var self = this;
      try {
        window.addEventListener('ai-cm-full-history', function (ev) {
          // detail есть только у CustomEvent, а addEventListener типизирует аргумент
          // как Event (TS2339) — сужаем форму через промежуточную переменную, сохраняя
          // прежнюю null-защиту (событие без detail обязано остаться безопасным).
          var evt = /** @type {CustomEvent} */ (ev);
          var detail = evt && evt.detail;
          if (detail && detail.modelSlug) {
            self._lastNetworkModel = detail.modelSlug;
          }
        });
        // handshake: сигналим перехватчику (MAIN world), что content.js уже подписан на ai-cm-full-history
        window.dispatchEvent(new CustomEvent('ai-cm-google-search-ready'));
      } catch (e) {}
    }
  }

  /**
   * Находимся ли мы на странице диалога AI-режима: есть turn-контейнеры,
   * блок ответа aimfl или поле ввода.
   * @returns {boolean}
   */
  isOnDialogPage() {
    var hasTurns = document.querySelector('[data-scope-id="turn"]') !== null;
    var hasAimfl = document.querySelector('[data-subtree="aimfl"]') !== null;
    var hasInput = document.querySelector('textarea, [contenteditable="true"]') !== null;
    var result = hasTurns || hasAimfl || hasInput;
    console.log('[GoogleSearchAdapter] Страница диалога: ' + result);
    return result;
  }

  /**
   * Ходы диалога: вопрос из заголовка turn'а, ответ — блоки ответа, отнесённые к
   * тому же turn'у. Пустые вопросы/ответы пропускаются; при ошибке — пустой массив.
   * @returns {GoogleSearchExtractedMessage[]}
   */
  extractMessages() {
    try {
      var turns = document.querySelectorAll('[data-scope-id="turn"]');
      if (!turns || turns.length === 0) {
        console.log('[GoogleSearchAdapter] Turn-контейнеров не найдено');
        return [];
      }

      // Собираем вопросы из h2.iMqumd внутри turn'ов
      /** @type {(string|null)[]} */
      var questions = [];
      for (var i = 0; i < turns.length; i++) {
        var h2 = turns[i].querySelector('h2.iMqumd');
        var qText = null;
        if (h2) {
          // Подпись локализована: ru/en — в кавычках, de — без них (de-DE-снимок: 6/6).
          var raw = h2.textContent.trim();
          var match = raw.match(/^(?:Вы сказали|You said|You asked):\s*"([\s\S]*)"$/) ||
            raw.match(/^Du hast Folgendes (?:gesagt|gesendet):\s*([\s\S]*)$/);
          if (match) {
            qText = match[1].trim();
          } else { qText = raw; }
        }
        questions.push(qText);
      }

      // Распределяем блоки .n6owBd.awi2gc по turn'ам
      /** @type {string[][]} */
      var answerBlocks = [];
      for (var ti = 0; ti < turns.length; ti++) {
        answerBlocks[ti] = [];
      }

      // O-45: узлы ответа — чанки прозы + САМОСТОЯТЕЛЬНЫЕ код-окна между ними (общий отбор
      // парсера answerDomNodes), текст узла — общим рендером answerTextOf: окно кода уезжает
      // в ```lang\n<код>\n``` целиком. Без доступного хелпера — прежний путь (только
      // .n6owBd.awi2gc и голый textContent), байты DOM-пути не меняются.
      var blocks = gsaAnswerNodes(document);
      for (var b = 0; b < blocks.length; b++) {
        var block = blocks[b];
        var assignedIdx = -1;
        for (var ti2 = 0; ti2 < turns.length; ti2++) {
          if (turns[ti2].compareDocumentPosition(block) & Node.DOCUMENT_POSITION_FOLLOWING) {
            assignedIdx = ti2;
          } else {
            break;
          }
        }
        if (assignedIdx >= 0 && assignedIdx < turns.length) {
          // gsaAnswerNodes отдаёт NodeList|Element[] — узлы ответа всегда элементы.
          var blockText = gsaAnswerText(/** @type {Element} */ (/** @type {unknown} */ (block))).trim();
          if (blockText) {
            answerBlocks[assignedIdx].push(blockText);
          }
        }
      }

      // O-45 (ДИАГНОСТИКА, только измерение): структура ПЕРВОГО найденного код-блока Gemini.
      // Гейт — aiCmDebug (utils/debug.js: aiCmDiagOn/aiCmDiagLine, тот же ISOLATED-мир).
      // Печатается ОДИН раз на блок (антиспам: extractMessages зовётся в цикле оценки токенов),
      // только ЧИТАЕТ DOM: извлечение текста, байты экспорта, пороги и латчи не меняются.
      // В срез-песочницах тестов хелперов гейта нет — вызовы защищены typeof-гардом.
      try {
        if (typeof aiCmDiagOn === 'function' && aiCmDiagOn() && typeof aiCmDiagLine === 'function') {
          var codeSels = ['.n6owBd.awi2gc pre', '.n6owBd.awi2gc code',
            '[data-subtree="aimfl"] pre', '[data-subtree="aimfl"] code', 'pre', 'code'];
          var codeEl = null, codeVia = '';
          for (var cs = 0; cs < codeSels.length && !codeEl; cs++) {
            codeEl = document.querySelector(codeSels[cs]);
            if (codeEl) codeVia = codeSels[cs];
          }
          var codeSig = codeEl
            ? (codeVia + '|' + codeEl.tagName + '|' + String(codeEl.className || '') + '|' + codeEl.textContent.length)
            : 'none';
          if (codeSig !== this._lastCodeBlockSig) {
            this._lastCodeBlockSig = codeSig;
            if (!codeEl) {
              aiCmDiagLine('gsa-code-block', { found: 0, via: '(нет)', blocks: blocks.length, turns: turns.length });
            } else {
              var codeParent = codeEl.parentElement;
              aiCmDiagLine('gsa-code-block', {
                found: 1,
                via: codeVia,
                tag: codeEl.tagName,
                cls: String(codeEl.className || '').slice(0, 120),
                childs: codeEl.childNodes.length,
                textLen: codeEl.textContent.length,
                parentTag: (codeParent && codeParent.tagName) || '',
                parentCls: (codeParent && String(codeParent.className || '').slice(0, 120)) || '',
                // outerHTML.slice(0,500); переводы строк схлопнуты, чтобы строка лога осталась одной
                html500: String(codeEl.outerHTML || '').replace(/\s+/g, ' ').slice(0, 500)
              });
            }
          }
        }
      } catch (eCodeBlock) { }

      // Собираем ответы
      /** @type {(string|null)[]} */
      var answers = [];
      for (var ti3 = 0; ti3 < turns.length; ti3++) {
        var joined = answerBlocks[ti3].length > 0 ? answerBlocks[ti3].join('\n\n') : null;
        // Фолбэк: [data-subtree="aimfl"] по индексу
        if (!joined) {
          var allAimfl = document.querySelectorAll('[data-subtree="aimfl"]');
          if (allAimfl[ti3]) {
            var aimText = allAimfl[ti3].textContent.trim();
            if (aimText) joined = aimText;
          }
        }
        answers.push(joined);
      }

      // Формируем сообщения: user → assistant, по порядку
      /** @type {GoogleSearchExtractedMessage[]} */
      var messages = [];
      for (var k = 0; k < Math.min(questions.length, answers.length); k++) {
        if (questions[k]) {
          messages.push({ role: 'user', content: questions[k] });
        }
        if (answers[k]) {
          messages.push({ role: 'assistant', content: answers[k] });
        }
      }

      // Антиспам: печатаем только при изменении N сообщений.
      if (messages.length !== this._lastExtractedCount) {
        this._lastExtractedCount = messages.length;
        console.log('[GoogleSearchAdapter] Извлечено ' + messages.length + ' сообщений');
      }
      return messages;
    } catch (error) {
      debugLog('error', '[GoogleSearchAdapter] Ошибка:', error);
      return [];
    }
  }

  /**
   * Полный текст диалога: содержимое ходов, склеенное переводом строки.
   * @returns {string}
   */
  getFullDialogText() {
    return this.extractMessages().map(function(msg) { return msg.content; }).join('\n');
  }

  /**
   * Модель: ТОЛЬКО из сети (активный/пассивный ответ, detail.modelSlug), иначе ''.
   * DOM-догадка сознательно не возвращается — см. комментарий в теле метода.
   * @returns {string}
   */
  detectModel() {
    // Модель берём ТОЛЬКО из сети (активный/пассивный ответ, detail.modelSlug).
    // Дефект: раньше фолбэк отдавал DOM-догадку gemini-2.5-flash, хотя в сети
    // ходит 1.5-pro/1.5-flash. Для GSA 2.5-flash не возвращаем никогда.
    if (this._lastNetworkModel) return this._lastNetworkModel;
    return '';
  }
}

